+/** The language for an Accept-Language header value, by q-value; `fallback` when none is supported. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [range, ...attrs] = part.trim().split(";");
+    const lang = range.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const attr of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(attr);
+      if (m) q = Number(m[1]);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) continue;
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
+
 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
